using StackExchange.Redis;

public class OrderingGuard
{
    private readonly IDatabase _redis;
    private const string KeyPrefix = "seq:";

    public OrderingGuard(IConnectionMultiplexer redis)
    {
        _redis = redis.GetDatabase();
    }

    public async Task<bool> TryAcceptAsync(string entityId, long sequence)
    {
        var key = KeyPrefix + entityId;
        var last = await _redis.StringGetAsync(key);

        if (last.HasValue && sequence <= (long)last)
        {
            return false; // duplicate or out-of-order
        }

        await _redis.StringSetAsync(key, sequence);
        return true;
    }
}

// Usage in consumer
var guard = new OrderingGuard(redis);
if (!await guard.TryAcceptAsync("order-123", msg.Sequence))
{
    await channel.NackAsync(deliveryTag, false, requeue: false);
    return;
}
